import sys
from array import array
from bisect import bisect_left

def solve(devices):
    # A coincident anchor needs only its two longest devices: one per direction.
    at={}
    for x,length in devices:
        if not length:
            continue
        top=at.get(x)
        if top is None:
            at[x]=(length,0)
        elif length>top[0]:
            at[x]=(length,top[0])
        elif length>top[1]:
            at[x]=(top[0],length)
    intervals=[]
    device=0
    for x,(a,b) in at.items():
        for length in (a,b):
            if length:
                intervals.append((x,x-length,device))
                intervals.append((x+length,x,device))
                device+=1
    intervals.sort()
    m=len(intervals)
    if not m:
        return 0
    rights=[r for r,l,d in intervals]
    lefts=[l for r,l,d in intervals]
    ids=[d for r,l,d in intervals]
    lengths=[r-l for r,l,d in intervals]
    bounds=[bisect_left(rights,l) for l in lefts]
    queries=sorted(set(bounds))
    query_rank=[0]*(m+1)
    for rank,q in enumerate(queries):
        query_rank[q]=rank
    suffix_min=[m]*(m+1)
    for j in range(m-1,-1,-1):
        suffix_min[j]=min(bounds[j],suffix_min[j+1])
    # For each prefix, the smallest left endpoints from two distinct devices.
    INF=10**30
    min1=[INF];min2=[INF];owner1=[-1]
    first=second=INF;first_id=second_id=-1
    starts=[];group_start=0
    for j,(right,left,dev) in enumerate(intervals):
        if j and right!=rights[j-1]:
            group_start=j
        starts.append(group_start)
        if dev==first_id:
            if left<first:
                first=left
        elif dev==second_id:
            if left<second:
                second=left
                if second<first:
                    first,second=second,first
                    first_id,second_id=second_id,first_id
        elif left<first:
            second,second_id=first,first_id
            first,first_id=left,dev
        elif left<second:
            second,second_id=left,dev
        min1.append(first);min2.append(second);owner1.append(first_id)
    # kind 0: constant base row. kind 1: bound=0 row, queried by a formula.
    # kind 2: only genuinely queried prefix entries, followed by a constant tail.
    kinds=[];rows=[];offsets=[];tails=[];tail_values=[]
    end_best=[];global_best=[]
    for j in range(m):
        left=lefts[j];right=rights[j];dev=ids[j];length=lengths[j]
        stop=starts[j]
        small_left=min2[stop] if owner1[stop]==dev else min1[stop]
        q=bounds[j]
        if small_left>=left:
            kind=0;best=length;row=None;lo=tail=0
        elif q==0:
            kind=1;best=max(length,right-small_left);row=None;lo=tail=0
        else:
            kind=2
            # Earlier disjoint intervals are answered by one global prefix.
            best=length+global_best[q-1]
            lo=bisect_left(queries,max(1,suffix_min[j+1]))
            hi=bisect_left(queries,j)
            row=array('I');write=lo
            while write<hi and queries[write]<=q:
                row.append(length+global_best[queries[write]-1]);write+=1
            upper=right-min1[j+1]
            if best<upper:
                qr=query_rank[q]
                for i in range(q,stop):
                    if lefts[i]<left and ids[i]!=dev:
                        ik=kinds[i]
                        if ik==0:
                            prior=lengths[i]
                        elif q>=i:
                            prior=end_best[i]
                        elif ik==1:
                            limit=q if q<starts[i] else starts[i]
                            ml=min2[limit] if owner1[limit]==ids[i] else min1[limit]
                            v=rights[i]-ml
                            prior=v if v>lengths[i] else lengths[i]
                        elif qr>=tails[i]:
                            prior=tail_values[i]
                        else:
                            prior=rows[i][qr-offsets[i]]
                        value=prior+right-rights[i]
                        if value>best:
                            best=value
                    if write<hi and queries[write]==i+1:
                        row.append(best);write+=1
                    if best==upper:
                        break
            # No later predecessor can beat an attained bounding-hull upper
            # bound, or add a strictly earlier endpoint after 'stop'.
            tail=write
        kinds.append(kind);rows.append(row);offsets.append(lo)
        tails.append(tail);tail_values.append(best);end_best.append(best)
        global_best.append(max(best,global_best[-1]) if global_best else best)
    return global_best[-1]

if __name__=='__main__':
    values=iter(map(int,sys.stdin.buffer.read().split()))
    output=[]
    for n in values:
        devices=[(next(values),next(values)) for _ in range(n)]
        output.append(str(solve(devices)))
    print('\n'.join(output))

